<div class="row justify-content-center"><div class="col-lg-8"><a class="small text-decoration-none" href="/calendar"><i class="bi bi-arrow-left me-1"></i>Back to calendar</a><article class="lh-card p-4 p-md-5 mt-3"><span class="lh-kicker"><?= e(date('l, F j, Y', strtotime($event['event_date']))) ?></span><h1 class="lh-page-title mt-2"><?= e($event['title']) ?></h1><div class="d-flex flex-wrap gap-3 text-secondary mb-4"><span><i class="bi bi-geo-alt me-1"></i><?= e($event['location']) ?></span><span><i class="bi bi-person me-1"></i><?= e($event['organizer']) ?></span><?php if ($event['start_time']): ?><span><i class="bi bi-clock me-1"></i><?= e(substr($event['start_time'], 0, 5)) ?><?= $event['end_time'] ? '–'.e(substr($event['end_time'], 0, 5)) : '' ?></span><?php endif; ?></div><p class="lh-lead"><?= nl2br(e($event['description'])) ?></p><?php if ($event['website_url']): ?><a class="btn btn-lh-primary" href="<?= e($event['website_url']) ?>" target="_blank" rel="noopener">Visit event website <i class="bi bi-arrow-up-right ms-2"></i></a><?php endif; ?><?php if ($event['status'] !== 'approved'): ?><div class="alert alert-warning mt-4 mb-0">This submission is currently <?= e($event['status']) ?> and is only visible to you and administrators.</div><?php endif; ?></article></div></div>
